import { describe, expect, it } from 'vitest'
import { parseBackup, saveRecoverySnapshot } from '../src/lib/backup'

const empty = { schemaVersion: 2, transactions: [], budgets: [], goals: [], dailyBudgets: [], accounts: [], contributions: [], plannedSpending: [], transfers: [], balanceAdjustments: [] }

describe('backup safety', () => {
  it('preserves valid legacy records and extra ledger fields', () => {
    const original = { ...empty, transactions: [{ id: 'saving', type: 'saving', amount: 50, date: '2026-10-03', savingType: 'Emergency', mode: 'opening', note: 'Keep me' }] }
    expect(parseBackup(JSON.parse(JSON.stringify(original))).transactions).toEqual(original.transactions)
  })
  it('rejects unsupported versions, impossible dates, missing accounts and duplicate IDs', () => {
    expect(() => parseBackup({ ...empty, schemaVersion: 999 })).toThrow()
    expect(() => parseBackup({ ...empty, dailyBudgets: [{ date: '2026-02-31', amount: 100 }] })).toThrow()
    expect(() => parseBackup({ ...empty, transactions: [{ id: 'income', type: 'income', source: 'Salary', notes: '', accountId: 'missing', date: '2026-10-03', amount: 100 }] })).toThrow('Missing referenced account')
    expect(() => parseBackup({ ...empty, goals: Array(2).fill({ id: 'goal', name: 'Reserve', currentAmount: 0, targetAmount: 100, deadline: '2026-12-31', color: 'blue' }) })).toThrow('Duplicate')
  })
  it('rejects unsafe profile and malformed values', () => {
    const missingCollection = { ...empty, schemaVersion: 3 } as Record<string, unknown>
    delete missingCollection.accounts
    expect(() => parseBackup(missingCollection)).toThrow('missing accounts')
    expect(() => parseBackup({ ...empty, transactions: [null] })).toThrow()
    expect(() => parseBackup({ ...empty, dailyBudgets: [{ date: '2026-10-03', amount: -1 }] })).toThrow()
    expect(() => parseBackup({ ...empty, profile: { dateFormat: 'unsupported' } })).toThrow()
  })
  it('does not swallow recovery storage failures', () => {
    const storage = { getItem: () => '{"state":{"transactions":[]},"version":3}', setItem: () => { throw new Error('Quota exceeded') } } as unknown as Storage
    expect(() => saveRecoverySnapshot(storage)).toThrow('Quota exceeded')
  })
})